from __future__ import annotations

from datetime import datetime

from sqlalchemy import select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.ext.asyncio import AsyncSession

from app.models.enums import OrderStatus, ReservationStatus
from app.models.order import Order
from app.models.reservation import Reservation
from app.models.sale import Sale


class ReservationNotFoundError(Exception):
    pass


class ReservationNotHeldError(Exception):
    pass


class ReservationAlreadyOrderedError(Exception):
    pass


class IdempotencyKeyReuseError(Exception):
    pass


async def list_user_orders(db: AsyncSession, user_id: int) -> list[Order]:
    return list(
        (
            await db.scalars(
                select(Order).where(Order.user_id == user_id).order_by(Order.id)
            )
        ).all()
    )


async def create_order(
    db: AsyncSession,
    reservation_id: int,
    user_id: int,
    idempotency_key: str,
    now: datetime,
) -> Order:
    # Idempotency: a repeated key returns the order it created, no second row.
    existing = (
        await db.execute(
            select(Order).where(
                Order.user_id == user_id,
                Order.idempotency_key == idempotency_key,
            )
        )
    ).scalar_one_or_none()
    if existing is not None:
        if existing.reservation_id != reservation_id:
            raise IdempotencyKeyReuseError
        return existing

    reservation = await db.scalar(
        select(Reservation).where(
            Reservation.id == reservation_id,
            Reservation.user_id == user_id,
        )
    )
    if reservation is None:
        raise ReservationNotFoundError
    if (
        reservation.status != ReservationStatus.HELD.value
        or reservation.expires_at <= now
    ):
        raise ReservationNotHeldError

    sale = await db.scalar(select(Sale).where(Sale.id == reservation.sale_id))
    if sale is None:
        raise ReservationNotFoundError

    order = Order(
        reservation_id=reservation_id,
        user_id=user_id,
        sale_id=reservation.sale_id,
        amount_minor=sale.price_minor,
        status=OrderStatus.PENDING.value,
        idempotency_key=idempotency_key,
    )
    db.add(order)
    try:
        await db.commit()
    except IntegrityError:
        await db.rollback()
        # A concurrent duplicate of the same key — return the row that won.
        existing = (
            await db.execute(
                select(Order).where(
                    Order.user_id == user_id,
                    Order.idempotency_key == idempotency_key,
                )
            )
        ).scalar_one_or_none()
        if existing is not None:
            if existing.reservation_id != reservation_id:
                raise IdempotencyKeyReuseError from None
            return existing
        raise ReservationAlreadyOrderedError from None
    return order

from __future__ import annotations

from typing import cast

from fastapi import Depends, HTTPException, Request
from sqlalchemy.ext.asyncio import AsyncSession

from app.clock import Clock
from app.config import Settings
from app.db import get_db
from app.models.enums import UserRole
from app.models.user import User
from app.paystub_client import PaystubClient
from app.realtime import Broadcaster
from app.services import auth

SESSION_COOKIE = "session"


def get_settings(request: Request) -> Settings:
    return cast(Settings, request.app.state.settings)


def get_clock(request: Request) -> Clock:
    return cast(Clock, request.app.state.clock)


def get_broadcaster(request: Request) -> Broadcaster:
    return cast(Broadcaster, request.app.state.broadcaster)


def get_paystub(request: Request) -> PaystubClient:
    return cast(PaystubClient, request.app.state.paystub)


async def current_user(
    request: Request,
    db: AsyncSession = Depends(get_db),
    clock: Clock = Depends(get_clock),
) -> User:
    token = request.cookies.get(SESSION_COOKIE)
    if token is None:
        raise HTTPException(status_code=401, detail="not authenticated")
    user = await auth.user_for_token(db, token, await clock.now())
    if user is None:
        raise HTTPException(status_code=401, detail="session expired")
    return user


async def require_shop(user: User = Depends(current_user)) -> User:
    if user.role != UserRole.SHOP.value:
        raise HTTPException(status_code=403, detail="shop role required")
    return user

