import { ref } from 'vue'
import { defineStore } from 'pinia'
import { api } from '../api/client'
import type { Order } from '../api/types'
import { useRealtime, type RealtimeEvent } from '../composables/useRealtime'

export const useOrdersStore = defineStore('orders', () => {
  const orders = ref<Order[]>([])

  async function fetchOrders(): Promise<void> {
    orders.value = await api.listOrders()
  }

  // The buyer's cabinet stays current via SSE: an order_status event means an
  // order moved (paid/cancelled), so refetch the list.
  async function applyEvent(event: RealtimeEvent): Promise<void> {
    if (event !== 'order_status') return
    try {
      await fetchOrders()
    } catch {
      // Transient refetch failure: the next event or reconnect retries.
    }
  }

  let bound = false
  function bindRealtime(): void {
    if (bound) return
    bound = true
    const rt = useRealtime()
    rt.on('order_status', () => void applyEvent('order_status'))
    rt.onReconnect(() => void fetchOrders())
  }

  return { orders, fetchOrders, applyEvent, bindRealtime }
})

import { ref } from 'vue'
import { defineStore } from 'pinia'
import { api } from '../api/client'
import type { Sale, SaleCreateInput, SaleStats } from '../api/types'
import { useRealtime, type RealtimeEvent } from '../composables/useRealtime'

export const useShopStore = defineStore('shop', () => {
  const sales = ref<Sale[]>([])
  const stats = ref<SaleStats | null>(null)
  const selectedSaleId = ref<number | null>(null)

  // Monotonic guards: a burst of events starts concurrent refetches, and a
  // slower, older response must not overwrite a newer one.
  let salesSeq = 0
  let statsSeq = 0

  async function fetchSales(): Promise<void> {
    const seq = ++salesSeq
    const list = await api.listSales()
    if (seq !== salesSeq) return
    sales.value = list
  }

  async function fetchStats(saleId: number): Promise<void> {
    const seq = ++statsSeq
    selectedSaleId.value = saleId
    const data = await api.saleStats(saleId)
    if (seq !== statsSeq) return
    stats.value = data
  }

  async function createSale(input: SaleCreateInput): Promise<Sale> {
    const sale = await api.createSale(input)
    await fetchSales()
    return sale
  }

  // "Check status" asks the paystub and applies the answer through the same
  // handler as the webhook, then refreshes the stats so a resolved payment
  // drops out of the pending list and revenue/sold move.
  async function checkPayment(reference: string): Promise<void> {
    await api.checkPayment(reference)
    if (selectedSaleId.value !== null) await fetchStats(selectedSaleId.value)
  }

  async function applyEvent(event: RealtimeEvent): Promise<void> {
    if (event !== 'stock_changed' && event !== 'sale_status') return
    try {
      await fetchSales()
      if (selectedSaleId.value !== null) await fetchStats(selectedSaleId.value)
    } catch {
      // Transient refetch failure: the next event or reconnect retries.
    }
  }

  let bound = false
  function bindRealtime(): void {
    if (bound) return
    bound = true
    const rt = useRealtime()
    rt.on('stock_changed', () => void applyEvent('stock_changed'))
    rt.on('sale_status', () => void applyEvent('sale_status'))
    rt.onReconnect(() => {
      void fetchSales()
      if (selectedSaleId.value !== null) void fetchStats(selectedSaleId.value)
    })
  }

  return {
    sales,
    stats,
    selectedSaleId,
    fetchSales,
    fetchStats,
    createSale,
    checkPayment,
    applyEvent,
    bindRealtime,
  }
})

import { ref } from 'vue'
import { defineStore } from 'pinia'
import { api } from '../api/client'
import type { Sale } from '../api/types'
import { useRealtime, type RealtimeEvent } from '../composables/useRealtime'

export const useSalesStore = defineStore('sales', () => {
  const sales = ref<Sale[]>([])
  // Offset between the browser clock and the backend's `server_now`, captured on
  // the last fetch. The UI counts down from `Date.now() - serverOffset`, so
  // "opens for everyone at once" depends on the backend clock, not the browser's.
  const serverOffset = ref<number | null>(null)

  // Monotonic guard: a burst of events starts several concurrent refetches, and
  // a slower, older response must not overwrite a newer one.
  let fetchSeq = 0

  async function fetchSales(): Promise<void> {
    const seq = ++fetchSeq
    const list = await api.listSales()
    if (seq !== fetchSeq) return
    sales.value = list
    serverOffset.value =
      list.length > 0 ? Date.now() - Date.parse(list[0]!.server_now) : null
  }

  async function reserve(saleId: number): Promise<void> {
    await api.reserve(saleId)
    await fetchSales()
  }

  // Applies a realtime event. Kept as its own (async) action so a test can feed
  // it events directly and assert the resulting state — the SSE wiring just
  // routes into it. The payload is not needed: stock/sale changes always
  // refetch the whole list.
  async function applyEvent(event: RealtimeEvent): Promise<void> {
    if (event !== 'stock_changed' && event !== 'sale_status') return
    try {
      await fetchSales()
    } catch {
      // A transient refetch failure is not worth surfacing; the next event or a
      // reconnect will retry.
    }
  }

  let bound = false
  function bindRealtime(): void {
    if (bound) return
    bound = true
    const rt = useRealtime()
    rt.on('stock_changed', () => void applyEvent('stock_changed'))
    rt.on('sale_status', () => void applyEvent('sale_status'))
    rt.onReconnect(() => void fetchSales())
  }

  return { sales, serverOffset, fetchSales, reserve, applyEvent, bindRealtime }
})

