// The single place that talks HTTP. Every request goes through the /api
// prefix so the Vite dev proxy and nginx route it to the backend without the
// browser knowing the origin; components and stores never call fetch directly.
//
// Session auth rides the HttpOnly cookie, so no token is threaded through
// here — the browser sends it on same-origin requests (the default
// `credentials` of 'same-origin').

import type {
  Cart,
  Order,
  PayResult,
  Reservation,
  Sale,
  SaleCreateInput,
  SaleStats,
  User,
} from './types'

export class ApiError extends Error {
  readonly status: number

  constructor(status: number, message: string) {
    super(message)
    this.name = 'ApiError'
    this.status = status
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let res: Response
  try {
    res = await fetch(`/api${path}`, {
      ...init,
      headers: { 'Content-Type': 'application/json', ...init?.headers },
    })
  } catch (e) {
    throw new ApiError(0, e instanceof Error ? e.message : 'network error')
  }
  if (!res.ok) {
    throw new ApiError(res.status, await detail(res))
  }
  if (res.status === 204) {
    return undefined as T
  }
  return (await res.json()) as T
}

async function detail(res: Response): Promise<string> {
  try {
    const body = (await res.json()) as { detail?: unknown }
    if (typeof body.detail === 'string') return body.detail
  } catch {
    // Non-JSON error body (proxy/nginx 502 etc.) — fall through to the status.
  }
  return `HTTP ${res.status}`
}

function post<T>(path: string, body: unknown): Promise<T> {
  return request<T>(path, { method: 'POST', body: JSON.stringify(body) })
}

export const api = {
  // auth
  register(email: string, password: string): Promise<User> {
    return post<User>('/auth/register', { email, password })
  },
  login(email: string, password: string): Promise<User> {
    return post<User>('/auth/login', { email, password })
  },
  logout(): Promise<void> {
    return request<void>('/auth/logout', { method: 'POST' })
  },
  me(): Promise<User> {
    return request<User>('/auth/me')
  },

  // sales
  listSales(): Promise<Sale[]> {
    return request<Sale[]>('/sales')
  },
  getSale(id: number): Promise<Sale> {
    return request<Sale>(`/sales/${id}`)
  },
  createSale(input: SaleCreateInput): Promise<Sale> {
    return post<Sale>('/sales', input)
  },
  reserve(saleId: number): Promise<Reservation> {
    return post<Reservation>(`/sales/${saleId}/reserve`, {})
  },

  // cart
  releaseReservation(reservationId: number): Promise<void> {
    return request<void>(`/reservations/${reservationId}`, { method: 'DELETE' })
  },
  cart(): Promise<Cart> {
    return request<Cart>('/me/cart')
  },
  listOrders(): Promise<Order[]> {
    return request<Order[]>('/me/orders')
  },

  // orders + payments
  createOrder(reservationId: number, idempotencyKey: string): Promise<Order> {
    return request<Order>('/orders', {
      method: 'POST',
      body: JSON.stringify({ reservation_id: reservationId }),
      headers: { 'Idempotency-Key': idempotencyKey },
    })
  },
  pay(orderId: number, cardNumber: string): Promise<PayResult> {
    return post<PayResult>(`/orders/${orderId}/pay`, { card_number: cardNumber })
  },

  // shop
  saleStats(saleId: number): Promise<SaleStats> {
    return request<SaleStats>(`/shop/sales/${saleId}/stats`)
  },
  checkPayment(reference: string): Promise<{ status: string }> {
    return post<{ status: string }>(`/shop/payments/${reference}/check`, {})
  },
}

from __future__ import annotations

from datetime import datetime
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, Field, field_validator, model_validator
from sqlalchemy.ext.asyncio import AsyncSession

from app.clock import Clock
from app.db import get_db
from app.deps import current_user, get_broadcaster, get_clock, require_shop
from app.models.sale import Sale
from app.models.user import User
from app.realtime import Broadcaster
from app.services import cart, sales as sales_service
from app.services.sales import InvalidSaleWindowError, SalePhase

router = APIRouter(prefix="/sales", tags=["sales"])


class SaleCreateRequest(BaseModel):
    title: str = Field(max_length=255)
    price_minor: int = Field(ge=0)
    quantity: int = Field(ge=1)
    timezone: str
    starts_at: datetime
    ends_at: datetime

    @field_validator("timezone")
    @classmethod
    def _validate_timezone(cls, value: str) -> str:
        try:
            ZoneInfo(value)
        except ZoneInfoNotFoundError:
            raise ValueError(f"unknown timezone: {value}") from None
        return value

    @field_validator("starts_at", "ends_at")
    @classmethod
    def _require_naive(cls, value: datetime) -> datetime:
        if value.tzinfo is not None:
            raise ValueError(
                "start/end times must be naive wall-clock; the timezone field carries the zone"
            )
        return value

    @model_validator(mode="after")
    def _check_window(self) -> SaleCreateRequest:
        if self.ends_at <= self.starts_at:
            raise ValueError("ends_at must be after starts_at")
        return self


class SaleResponse(BaseModel):
    id: int
    title: str
    price_minor: int
    quantity: int
    available: int
    starts_at: datetime
    ends_at: datetime
    timezone: str
    phase: SalePhase
    server_now: datetime


def _to_response(sale: Sale, now: datetime) -> SaleResponse:
    return SaleResponse(
        id=sale.id,
        title=sale.title,
        price_minor=sale.price_minor,
        quantity=sale.quantity,
        available=sale.available,
        starts_at=sale.starts_at,
        ends_at=sale.ends_at,
        timezone=sale.timezone,
        phase=sales_service.phase(sale.starts_at, sale.ends_at, now),
        server_now=now,
    )


@router.get("", response_model=list[SaleResponse])
async def list_sales(
    db: AsyncSession = Depends(get_db),
    clock: Clock = Depends(get_clock),
) -> list[SaleResponse]:
    now = await clock.now()
    return [_to_response(sale, now) for sale in await sales_service.list_sales(db)]


@router.get("/{sale_id}", response_model=SaleResponse)
async def get_sale(
    sale_id: int,
    db: AsyncSession = Depends(get_db),
    clock: Clock = Depends(get_clock),
) -> SaleResponse:
    sale = await sales_service.get_sale(db, sale_id)
    if sale is None:
        raise HTTPException(status_code=404, detail="sale not found")
    return _to_response(sale, await clock.now())


@router.post("", status_code=201, response_model=SaleResponse)
async def create_sale(
    body: SaleCreateRequest,
    db: AsyncSession = Depends(get_db),
    clock: Clock = Depends(get_clock),
    _shop: object = Depends(require_shop),
) -> SaleResponse:
    try:
        sale = await sales_service.create_sale(
            db,
            title=body.title,
            price_minor=body.price_minor,
            quantity=body.quantity,
            tz_name=body.timezone,
            starts_at_local=body.starts_at,
            ends_at_local=body.ends_at,
        )
    except InvalidSaleWindowError:
        raise HTTPException(
            status_code=422,
            detail="ends_at must be after starts_at in the sale's timezone",
        ) from None
    return _to_response(sale, await clock.now())


class ReservationResponse(BaseModel):
    id: int
    sale_id: int
    status: str
    expires_at: datetime


@router.post("/{sale_id}/reserve", status_code=201, response_model=ReservationResponse)
async def reserve(
    sale_id: int,
    db: AsyncSession = Depends(get_db),
    clock: Clock = Depends(get_clock),
    broadcaster: Broadcaster = Depends(get_broadcaster),
    user: User = Depends(current_user),
) -> ReservationResponse:
    try:
        reservation = await cart.reserve(
            db, sale_id, user.id, await clock.now(), broadcaster
        )
    except cart.NotStartedError:
        raise HTTPException(
            status_code=409, detail="sale has not started yet"
        ) from None
    except cart.SaleEndedError:
        raise HTTPException(status_code=409, detail="sale has ended") from None
    except cart.SoldOutError:
        raise HTTPException(status_code=409, detail="sold out") from None
    except cart.AlreadyInCartError:
        raise HTTPException(status_code=409, detail="already in cart") from None
    except cart.SaleNotFoundError:
        raise HTTPException(status_code=404, detail="sale not found") from None
    return ReservationResponse(
        id=reservation.id,
        sale_id=reservation.sale_id,
        status=reservation.status,
        expires_at=reservation.expires_at,
    )

from __future__ import annotations

from datetime import timedelta

from fastapi import APIRouter, Depends, HTTPException, Request, Response
from pydantic import BaseModel, EmailStr, field_validator
from sqlalchemy.ext.asyncio import AsyncSession

from app.clock import Clock
from app.config import Settings
from app.db import get_db
from app.deps import SESSION_COOKIE, current_user, get_clock, get_settings
from app.models.user import User
from app.services import auth

router = APIRouter(prefix="/auth", tags=["auth"])


class CredentialsRequest(BaseModel):
    email: EmailStr
    password: str

    @field_validator("email", mode="before")
    @classmethod
    def _normalize_email(cls, value: str) -> str:
        return value.strip().lower()


class UserResponse(BaseModel):
    id: int
    email: str
    role: str


@router.post("/register", status_code=201, response_model=UserResponse)
async def register(
    body: CredentialsRequest,
    db: AsyncSession = Depends(get_db),
) -> UserResponse:
    try:
        user = await auth.register(db, body.email, body.password)
    except auth.EmailTakenError:
        raise HTTPException(
            status_code=409, detail="email already registered"
        ) from None
    return UserResponse(id=user.id, email=user.email, role=user.role)


@router.post("/login", response_model=UserResponse)
async def login(
    body: CredentialsRequest,
    response: Response,
    db: AsyncSession = Depends(get_db),
    clock: Clock = Depends(get_clock),
    settings: Settings = Depends(get_settings),
) -> UserResponse:
    ttl = timedelta(days=settings.session_ttl_days)
    try:
        token, user = await auth.login(
            db, body.email, body.password, await clock.now(), ttl
        )
    except auth.InvalidCredentialsError:
        raise HTTPException(
            status_code=401, detail="invalid email or password"
        ) from None
    response.set_cookie(
        SESSION_COOKIE,
        token,
        max_age=int(ttl.total_seconds()),
        httponly=True,
        samesite="lax",
        secure=settings.app_env != "dev",
    )
    return UserResponse(id=user.id, email=user.email, role=user.role)


@router.post("/logout", status_code=204)
async def logout(
    request: Request,
    db: AsyncSession = Depends(get_db),
) -> Response:
    token = request.cookies.get(SESSION_COOKIE)
    if token is not None:
        await auth.logout(db, token)
    response = Response(status_code=204)
    response.delete_cookie(SESSION_COOKIE)
    return response


@router.get("/me", response_model=UserResponse)
async def me(user: User = Depends(current_user)) -> UserResponse:
    return UserResponse(id=user.id, email=user.email, role=user.role)

